-- Serbia story: EN/ES/DE/FR, covering the e-otpremnica (e-delivery
-- note) Phase 1 launch -- a real, dated news event (a new statute
-- taking effect, with a since-completed grace period) independently
-- researched and confirmed in this session against Serbia's Ministry
-- of Finance legal-text pages and cross-checked against several
-- independent secondary summaries (Comarch, VATupdate, docloop.rs,
-- injac.rs) that agree on the two-phase structure.

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-01-01-serbia-eotpremnica-phase1', '2026-01-01', '2026-01', 'From 1 January 2026, Serbia''s new e-otpremnica (e-delivery note) system became mandatory for public-sector entities, excise-goods traders, and carriers -- a separate obligation from the SEF e-invoicing mandate that has applied since 2023. A grace period ran to 30 June 2026 before full inspection enforcement began; a second phase extends the obligation to the general private sector on 1 October 2027.', '<h3>🇷🇸 Serbia''s e-delivery-note system goes live for Phase 1 obligors</h3>
<p>Serbia has required B2B e-invoicing through its SEF (Sistem elektronskih faktura) platform since 1 January 2023. From 1 January 2026, a separate, newer statute -- the Zakon o elektronskim otpremnicama -- added a parallel obligation: electronic delivery notes (e-otpremnica) for goods movement, tracked through its own central platform.</p>
<p>Phase 1 covers public-sector entities, traders in excise goods (fuel, alcohol, tobacco, e-cigarettes, electricity, coffee), and carriers presenting waybills at roadside inspection. A grace period ran to 30 June 2026, after which full inspection enforcement began. The law sets its own tiered penalties, distinct from the e-invoicing law''s fines.</p>
<p>A second phase, effective 1 October 2027, extends the e-otpremnica obligation to general private-sector B2B goods movement. Separately, secondary sources report a broader "expanded B2B" e-invoicing reform package (new SEF fields, stricter validation, a new penalty regime) targeting "end of 2026," though its exact date has not been confirmed via a primary government announcement.</p>', 'https://mfin.gov.rs/sr/propisi-1/zakon-o-elektronskim-otpremnicama-slubeni-glasnik-rs-br-942024-i-1092025-nezvanino-preien-tekst-redakcije-slubenog-glasnika-1', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-01-01-serbia-eotpremnica-phase1', id FROM countries WHERE code = 'RS';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-serbia-eotpremnica-phase1', 'en', 'Serbia''s e-delivery-note system goes live for Phase 1 obligors', 'From 1 January 2026, Serbia''s new e-otpremnica (e-delivery note) system became mandatory for public-sector entities, excise-goods traders, and carriers -- a separate obligation from the SEF e-invoicing mandate that has applied since 2023. A grace period ran to 30 June 2026 before full inspection enforcement began; a second phase extends the obligation to the general private sector on 1 October 2027.', '<h3>🇷🇸 Serbia''s e-delivery-note system goes live for Phase 1 obligors</h3>
<p>Serbia has required B2B e-invoicing through its SEF (Sistem elektronskih faktura) platform since 1 January 2023. From 1 January 2026, a separate, newer statute -- the Zakon o elektronskim otpremnicama -- added a parallel obligation: electronic delivery notes (e-otpremnica) for goods movement, tracked through its own central platform.</p>
<p>Phase 1 covers public-sector entities, traders in excise goods (fuel, alcohol, tobacco, e-cigarettes, electricity, coffee), and carriers presenting waybills at roadside inspection. A grace period ran to 30 June 2026, after which full inspection enforcement began. The law sets its own tiered penalties, distinct from the e-invoicing law''s fines.</p>
<p>A second phase, effective 1 October 2027, extends the e-otpremnica obligation to general private-sector B2B goods movement. Separately, secondary sources report a broader "expanded B2B" e-invoicing reform package (new SEF fields, stricter validation, a new penalty regime) targeting "end of 2026," though its exact date has not been confirmed via a primary government announcement.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-serbia-eotpremnica-phase1', 'es', 'El sistema serbio de albaranes electrónicos entra en vigor para los obligados de la Fase 1', 'Desde el 1 de enero de 2026, el nuevo sistema serbio de albaranes electrónicos (e-otpremnica) se volvió obligatorio para las entidades del sector público, los comerciantes de productos sujetos a impuestos especiales y los transportistas -- una obligación independiente del mandato de facturación electrónica SEF vigente desde 2023. Un período de gracia se extendió hasta el 30 de junio de 2026, antes de que comenzara la aplicación plena de las inspecciones; una segunda fase extiende la obligación al sector privado en general el 1 de octubre de 2027.', '<h3>🇷🇸 El sistema serbio de albaranes electrónicos entra en vigor para los obligados de la Fase 1</h3>
<p>Serbia exige la facturación electrónica B2B a través de su plataforma SEF (Sistem elektronskih faktura) desde el 1 de enero de 2023. Desde el 1 de enero de 2026, un estatuto separado y más reciente -- la Zakon o elektronskim otpremnicama -- añadió una obligación paralela: albaranes electrónicos (e-otpremnica) para el movimiento de mercancías, seguidos a través de su propia plataforma central.</p>
<p>La Fase 1 cubre a las entidades del sector público, los comerciantes de productos sujetos a impuestos especiales (combustible, alcohol, tabaco, cigarrillos electrónicos, electricidad, café) y los transportistas que presentan albaranes en inspecciones en carretera. Un período de gracia se extendió hasta el 30 de junio de 2026, tras el cual comenzó la aplicación plena de las inspecciones. La ley establece sus propias sanciones escalonadas, distintas de las multas de la ley de facturación electrónica.</p>
<p>Una segunda fase, vigente desde el 1 de octubre de 2027, extiende la obligación de e-otpremnica al movimiento general de mercancías B2B del sector privado. Por separado, fuentes secundarias informan de un paquete más amplio de reformas de facturación electrónica B2B (nuevos campos en SEF, validación más estricta, un nuevo régimen de sanciones) previsto para "fines de 2026", aunque su fecha exacta no se ha confirmado mediante un anuncio gubernamental primario.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-serbia-eotpremnica-phase1', 'de', 'Serbiens System für elektronische Lieferscheine geht für Phase-1-Verpflichtete live', 'Ab dem 1. Januar 2026 wurde Serbiens neues e-otpremnica-System (elektronischer Lieferschein) für öffentliche Einrichtungen, Händler verbrauchsteuerpflichtiger Waren und Beförderungsunternehmen verpflichtend -- eine eigenständige Pflicht neben der seit 2023 geltenden SEF-E-Rechnungspflicht. Eine Übergangsfrist lief bis zum 30. Juni 2026, bevor die vollständige Kontrolldurchsetzung begann; eine zweite Phase weitet die Pflicht am 1. Oktober 2027 auf den allgemeinen privaten Sektor aus.', '<h3>🇷🇸 Serbiens System für elektronische Lieferscheine geht für Phase-1-Verpflichtete live</h3>
<p>Serbien verlangt seit dem 1. Januar 2023 B2B-E-Rechnungsstellung über seine SEF-Plattform (Sistem elektronskih faktura). Ab dem 1. Januar 2026 fügte ein gesondertes, neueres Gesetz -- die Zakon o elektronskim otpremnicama -- eine parallele Pflicht hinzu: elektronische Lieferscheine (e-otpremnica) für den Warenverkehr, erfasst über eine eigene zentrale Plattform.</p>
<p>Phase 1 betrifft öffentliche Einrichtungen, Händler verbrauchsteuerpflichtiger Waren (Kraftstoff, Alkohol, Tabak, E-Zigaretten, Strom, Kaffee) und Beförderungsunternehmen, die bei Straßenkontrollen Lieferscheine vorlegen. Eine Übergangsfrist lief bis zum 30. Juni 2026, danach begann die vollständige Kontrolldurchsetzung. Das Gesetz sieht eigene, gestaffelte Bußgelder vor, getrennt von den Bußgeldern des E-Rechnungsgesetzes.</p>
<p>Eine zweite Phase, wirksam ab dem 1. Oktober 2027, weitet die e-otpremnica-Pflicht auf den allgemeinen privaten B2B-Warenverkehr aus. Gesondert berichten Sekundärquellen von einem umfassenderen "erweiterten B2B"-E-Rechnungsreformpaket (neue SEF-Felder, strengere Validierung, ein neues Bußgeldregime), das "Ende 2026" anvisiert, wobei das genaue Datum nicht durch eine primäre Regierungsankündigung bestätigt wurde.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-serbia-eotpremnica-phase1', 'fr', 'Le système serbe de bons de livraison électroniques entre en vigueur pour les assujettis de la phase 1', 'À compter du 1er janvier 2026, le nouveau système serbe e-otpremnica (bon de livraison électronique) est devenu obligatoire pour les entités du secteur public, les négociants en produits soumis à accise et les transporteurs -- une obligation distincte de l''obligation de facturation électronique SEF en vigueur depuis 2023. Une période de grâce a couru jusqu''au 30 juin 2026, avant le début de l''application intégrale des contrôles ; une seconde phase étend l''obligation au secteur privé en général le 1er octobre 2027.', '<h3>🇷🇸 Le système serbe de bons de livraison électroniques entre en vigueur pour les assujettis de la phase 1</h3>
<p>La Serbie exige la facturation électronique B2B via sa plateforme SEF (Sistem elektronskih faktura) depuis le 1er janvier 2023. À compter du 1er janvier 2026, une loi distincte et plus récente -- la Zakon o elektronskim otpremnicama -- a ajouté une obligation parallèle : des bons de livraison électroniques (e-otpremnica) pour le mouvement des marchandises, suivis via sa propre plateforme centrale.</p>
<p>La phase 1 couvre les entités du secteur public, les négociants en produits soumis à accise (carburant, alcool, tabac, cigarettes électroniques, électricité, café) et les transporteurs présentant des bons de livraison lors des contrôles routiers. Une période de grâce a couru jusqu''au 30 juin 2026, après quoi l''application intégrale des contrôles a commencé. La loi prévoit ses propres amendes échelonnées, distinctes de celles de la loi sur la facturation électronique.</p>
<p>Une seconde phase, effective au 1er octobre 2027, étend l''obligation e-otpremnica au mouvement général de marchandises B2B du secteur privé. Par ailleurs, des sources secondaires font état d''un paquet de réformes plus large de la facturation électronique B2B (nouveaux champs SEF, validation plus stricte, nouveau régime de sanctions) visant "fin 2026", bien que sa date exacte n''ait pas été confirmée par une annonce gouvernementale primaire.</p>');
